//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_aircraftAttitude(value: *mut FlightStack::AircraftAttitude) -> bool;
  fn put_qualifiedAttitude(value: *mut FlightStack::QualifiedAttitude) -> bool;
}

pub fn unsafe_get_aircraftAttitude() -> FlightStack::AircraftAttitude
{
  unsafe {
    let value: *mut FlightStack::AircraftAttitude = &mut FlightStack::AircraftAttitude::default();
    get_aircraftAttitude(value);
    return *value;
  }
}

pub fn unsafe_put_qualifiedAttitude(value: &FlightStack::QualifiedAttitude) -> bool
{
  unsafe {
    return put_qualifiedAttitude(value as *const FlightStack::QualifiedAttitude as *mut FlightStack::QualifiedAttitude);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_aircraftAttitude: Mutex<Option<FlightStack::AircraftAttitude>> = Mutex::new(None);
  pub static ref OUT_qualifiedAttitude: Mutex<Option<FlightStack::QualifiedAttitude>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_aircraftAttitude.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_aircraftAttitude(value: *mut FlightStack::AircraftAttitude) -> bool
{
  unsafe {
    let guard = IN_aircraftAttitude.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_qualifiedAttitude(value: *mut FlightStack::QualifiedAttitude) -> bool
{
  unsafe {
    *OUT_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
